param([switch]$Worker)
$ErrorActionPreference='Stop';$workspace=(Resolve-Path (Join-Path $PSScriptRoot '../../../..')).Path;$root=Join-Path $env:LOCALAPPDATA 'AgentPlatform/adjudication-model-v1/product-runtime'
if(-not $Worker){if(Get-NetTCPConnection -LocalPort 5445 -State Listen -ErrorAction SilentlyContinue){throw 'Preserve existing listener'};$p=Start-Process pwsh.exe -WindowStyle Hidden -ArgumentList @('-NoProfile','-File',$PSCommandPath,'-Worker') -PassThru -RedirectStandardOutput "$root/agent-runtime-wrapper-20261006.log" -RedirectStandardError "$root/agent-runtime-wrapper-error-20261006.log";$p.Id|Set-Content "$root/agent-runtime-wrapper-20261006.pid";Write-Output "CONTROLLED_RUNTIME_WRAPPER_PID=$($p.Id)";return}
function Secret($file){$secure=Import-Clixml -LiteralPath $file;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure);try{[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr)}}
$release=Get-Content "$root/current-release.json" -Raw|ConvertFrom-Json;$jar=[IO.Path]::GetFullPath($release.jar);if(-not $jar.StartsWith([IO.Path]::GetFullPath($root)+[IO.Path]::DirectorySeparatorChar) -or (Get-FileHash -LiteralPath $jar).Hash.ToLowerInvariant() -ne $release.sha256){throw 'Controlled release invalid'}
$config=[ordered]@{
 'server.address'='127.0.0.1';'server.port'=5445;'server.ssl.enabled'=$true;'server.ssl.key-store'="$root/server.p12";'server.ssl.key-store-type'='PKCS12';'server.ssl.key-store-password'=(Secret "$root/tls.credential.xml");'server.ssl.trust-store'="$root/trust.p12";'server.ssl.trust-store-type'='PKCS12';'server.ssl.trust-store-password'=(Secret "$root/tls.credential.xml");'server.ssl.client-auth'='want';
 'spring.profiles.active'='adjudication-product';'spring.main.banner-mode'='off';'logging.level.root'='WARN';
 'spring.datasource.url'='jdbc:dm://127.0.0.1:5301';'spring.datasource.username'='ADJLLM20261003';'spring.datasource.password'=(Secret (Join-Path (Split-Path -Parent $root) 'dm8-model-schema.credential.xml'));'spring.datasource.driver-class-name'='dm.jdbc.driver.DmDriver';
 'product.identity.enabled'=$true;'product.identity.issuer'='https://localhost:5445';'product.identity.audience'='adjudication-work-api';'product.identity.master-key'=(Secret "$root/identity-master.credential.xml");'product.identity.token-verification-window'='PT10M';'product.identity.activation-lifetime'='PT10M';'product.identity.minimum-password-length'=16;
 'product.identity.authority.jdbc-url'='jdbc:dm://127.0.0.1:5370';'product.identity.authority.username'='ADJAUTH_SVC';'product.identity.authority.password'=(Secret "$root/authority-service.credential.xml");'product.identity.authority.schema'='ADJAUTH20261004';
 'adjudication.v2.enabled'=$true;'adjudication.v2.identity-administration.enabled'=$true;'adjudication.v2.identity-administration.organization'='project-adjudication';
 'adjudication.v2.materials.enabled'=$false;'agent-platform.runtime.enabled'=$true;'agent-platform.runtime.checkpoint-key'=(Secret "$root/runtime-checkpoint-key-20261006.credential.xml")
}
$old=$env:SPRING_APPLICATION_JSON
try{$env:SPRING_APPLICATION_JSON=$config|ConvertTo-Json -Compress -Depth 8;$p=Start-Process 'D:/software/jdk-21/bin/java.exe' -WindowStyle Hidden -ArgumentList @('-Dloader.main=cn.xinji.agentplatform.adjudication.casework.ProductAdjudicationApplication','-cp',$jar,'org.springframework.boot.loader.launch.PropertiesLauncher') -WorkingDirectory $workspace -PassThru -RedirectStandardOutput "$root/agent-runtime-service-20261006.log" -RedirectStandardError "$root/agent-runtime-service-error-20261006.log";$p.Id|Set-Content "$root/runtime.pid" -Encoding ascii;$p.WaitForExit();if($p.ExitCode -ne 0){throw 'Controlled service startup failed; inspect private diagnostics'}}finally{$env:SPRING_APPLICATION_JSON=$old;$config=$null}

